const body = $json.body ?? {};
const errors = [];
const allowedPlatforms = ["facebook", "instagram", "linkedin", "tiktok"];

function requirePositiveInteger(field, label) {
  const value = Number(body[field]);
  if (!Number.isInteger(value) || value < 1) errors.push(label + " must be a positive number");
  return value;
}

function requireText(field, label) {
  const value = String(body[field] ?? "").trim();
  if (!value) errors.push(label + " is required");
  return value;
}

function optionalText(field) {
  return String(body[field] ?? "").trim();
}

const customerId = requirePositiveInteger("customer_id", "Customer ID");
const brandProfileId = requirePositiveInteger("brand_profile_id", "Brand profile ID");
const brandName = requireText("brand_name", "Brand name");
const platform = requireText("platform", "Platform").toLowerCase();
const topic = requireText("topic", "Topic");
const contentPillar = requireText("content_pillar", "Content pillar").toLowerCase();
const goal = requireText("goal", "Goal").toLowerCase();

if (!allowedPlatforms.includes(platform)) {
  errors.push("Platform is invalid");
}

if (errors.length > 0) {
  return [{ json: { valid: false, response: { success: false, message: "Validation failed", error: errors.join("; ") } } }];
}

return [{
  json: {
    valid: true,
    body: {
      customer_id: customerId,
      brand_profile_id: brandProfileId,
      brand_name: brandName,
      target_audience: optionalText("target_audience"),
      brand_voice: optionalText("brand_voice"),
      default_cta: optionalText("default_cta"),
      words_to_use: optionalText("words_to_use"),
      platform,
      topic,
      content_pillar: contentPillar,
      goal,
      campaign: optionalText("campaign"),
      offer: optionalText("offer"),
      call_to_action: optionalText("call_to_action")
    }
  }
}];

const body = $json.body;

function buildHashtagSeed(input) {
  return String(input ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => `#${word}`)
    .join(" ");
}

const audience = body.target_audience || "your audience";
const voice = body.brand_voice || "clear";
const callToAction = body.call_to_action || body.default_cta || "Send a message to learn more";
const preferredWords = body.words_to_use || body.brand_name;
const campaign = body.campaign || body.brand_name;
const offer = body.offer || "your offer";

const caption = [
  `${body.brand_name} | ${body.platform.toUpperCase()}`,
  `Topic: ${body.topic}.`,
  `Angle: ${body.content_pillar} with goal ${body.goal}.`,
  `Write for ${audience} in a ${voice} voice.`,
  `Connect the message to ${campaign} and ${offer}.`,
  `Use language such as ${preferredWords}.`,
  `CTA: ${callToAction}.`
].join(' ');

const hashtags = [
  buildHashtagSeed(body.platform),
  buildHashtagSeed(body.content_pillar),
  buildHashtagSeed(campaign)
].filter(Boolean).join(' ');

return [{ json: { success: true, caption, hashtags } }];

const body = $json.body;

function parseJsonContent(content) {
  const raw = String(content ?? "").trim();
  const cleaned = raw.replace(/^```(?:json)?/i, "").replace(/```$/i, "").trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("{");
    const end = cleaned.lastIndexOf("}");
    if (start >= 0 && end > start) {
      return JSON.parse(cleaned.slice(start, end + 1));
    }
    throw new Error("Model did not return valid JSON");
  }
}

async function callDeepSeek(messages) {
  const apiKey = $env.DEEPSEEK_API_KEY;

  if (!apiKey) {
    throw new Error("Missing DEEPSEEK_API_KEY in n8n environment");
  }

  const data = await this.helpers.httpRequest({
    method: "POST",
    url: "https://api.deepseek.com/chat/completions",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + apiKey
    },
    body: {
      model: "deepseek-chat",
      temperature: 0.7,
      response_format: { type: "json_object" },
      messages
    },
    json: true
  });

  return data?.choices?.[0]?.message?.content;
}

function cleanText(value) {
  return String(value ?? "").trim();
}

try {
  const content = await callDeepSeek([
    {
      role: "system",
      content: "You are a social media copywriter. Return only valid JSON with shape {\"success\":true,\"caption\":string,\"hashtags\":string}. Do not include markdown."
    },
    {
      role: "user",
      content: JSON.stringify({
        task: "Generate one caption",
        brand_name: body.brand_name,
        target_audience: body.target_audience,
        brand_voice: body.brand_voice,
        default_cta: body.default_cta,
        words_to_use: body.words_to_use,
        platform: body.platform,
        topic: body.topic,
        content_pillar: body.content_pillar,
        goal: body.goal,
        campaign: body.campaign,
        offer: body.offer,
        call_to_action: body.call_to_action,
        requirements: [
          "Write in a practical marketing style",
          "Keep the caption ready to paste into the platform",
          "Hashtags must be a space-separated string"
        ]
      })
    }
  ]);

  const parsed = parseJsonContent(content);
  const caption = cleanText(parsed.caption);

  if (!caption) {
    throw new Error("DeepSeek returned an empty caption");
  }

  return [{ json: { success: true, caption, hashtags: cleanText(parsed.hashtags) } }];
} catch (error) {
  return [{ json: { success: false, message: "AI caption generation failed", error: error instanceof Error ? error.message : String(error) } }];
}
